{"content": "1|/// **Option A**: GEMM-based attention using existing mma.sync kernel.
2|pub struct GemmBasedAttentionKernel {
3|    gemm_kernel: CudaGemmKernel,
4|    backend: std::sync::Arc<crate::kernel::memory::CudaMemoryBackend>,
5|    softmax_kernel: Box<dyn SoftmaxKernel>,
6|}
7|
8|impl GemmBasedAttentionKernel {
9|    pub fn new(
10|        gemm_kernel: CudaGemmKernel,
11|        backend: std::sync::Arc<crate::kernel::memory::CudaMemoryBackend>,
12|        softmax_kernel: Box<dyn SoftmaxKernel>,
13|    ) -> Self {
14|        Self {
15|            gemm_kernel,
16|            backend,
17|            softmax_kernel,
18|        }
19|    }
20|
21|    /// Forward pass for GEMM-based attention.
22|    pub fn forward(
23|        &self,
24|        query: &DeviceBuffer<f16>,
25|        key_cache: &Kvcache,
26|        value_cache: &Kvcache,
27|        _mask: Option<&DeviceBuffer<f32>>,
28|        config: &AttentionConfig,
29|    ) -> Result<DeviceBuffer<f32>, AttentionError> {
30|        let num_heads = config.num_heads;
31|        let head_dim = config.head_dim;
32|        let n = key_cache.seq_len();
33|        let query_seq_len = (query.len() / (num_heads * head_dim)) as usize;
34|
35|        println!(
36|            "GEMM attention: Q[{}, {}] x K[{}, {}] -> scores[{}, {}]",
37|            query_seq_len, num_heads, n, num_heads, query_seq_len, n
38|        );
39|
40|        // Step 1: Q @ K^T -> scores [query_seq_len * num_heads, n]
41|        let q_m = query_seq_len * num_heads;
42|        let q_k = head_dim;
43|        let k_n = n;
44|
45|        // Allocate scores buffer on device
46|        let mut scores_buffer = DeviceBuffer::<f32>::zeros_device(&self.backend, q_m * k_n)
47|            .map_err(|e| AttentionError::Cuda(format!("scores alloc: {e}")))?;
48|
49|        // Launch Q @ K^T via GEMM (mma.sync tensor cores)
50|        self.gemm_kernel
51|            .matmul(
52|                1.0, // alpha
53|                query,
54|                key_cache.buffer(),
55|                0.0, // beta (don't accumulate)
56|                &mut scores_buffer,
57|                q_m, // m = query_seq_len * num_heads
58|                k_n, // n = cache_seq_len (K is transposed)
59|                q_k, // k = head_dim
60|            )
61|            .map_err(|e| AttentionError::Gemm(e))?;
62|
63|        // Synchronize stream to ensure GEMM completes
64|        self.gemm_kernel.stream().synchronize()?;
65|
66|        // Step 2: Read back scores and apply softmax on CPU
67|        let mut scores_host = scores_buffer
68|            .to_host_vec(&self.backend)
69|            .map_err(|e| AttentionError::Transfer(e))?;
70|
71|        // Apply scaling factor (1/sqrt(head_dim))
72|        for score in scores_host.iter_mut() {
73|            *score *= config.scale;
74|        }
75|
76|        // Step 3: Softmax on cache_seq_len dimension
77|        let softmax_scores = self.softmax_1d(&scores_host, query_seq_len * num_heads, n);
78|
79|        // Step 4: S @ V -> output [query_seq_len, num_heads, head_dim]
80|        let s_m = query_seq_len * num_heads;
81|        let s_k = n;
82|        let v_n = head_dim;
83|
84|        // Convert softmax scores to f16 and allocate on device
85|        let softmax_scores_f16: Vec<f16> =
86|            softmax_scores.iter().map(|&x| f16::from_f32(x)).collect();
87|        let softmax_buf = DeviceBuffer::from_host_device(&self.backend, &softmax_scores_f16)
88|            .map_err(|e| AttentionError::Cuda(format!("softmax buf alloc: {e}")))?;
89|
90|        let mut output_buffer = DeviceBuffer::<f32>::zeros_device(&self.backend, s_m * v_n)
91|            .map_err(|e| AttentionError::Cuda(format!("output alloc: {e}")))?;
92|
93|        // Launch S @ V via GEMM (V is transposed)
94|        self.gemm_kernel
95|            .matmul(
96|                1.0,                  // alpha
97|                &softmax_buf,         // S (f16)
98|                value_cache.buffer(), // V (f16)
99|                0.0,                  // beta
100|                &mut output_buffer,
101|                s_m, // m = query_seq_len * num_heads
102|                v_n, // n = head_dim
103|                s_k, // k = cache_seq_len (V is transposed)
104|            )
105|            .map_err(|e| AttentionError::Gemm(e))?;
106|
107|        // Synchronize before returning
108|        self.gemm_kernel.stream().synchronize()?;
109|
110|        Ok(output_buffer)
111|    }
112|
113|    /// 1D softmax along the last dimension.
114|    fn softmax_1d(&self, scores: &[f32], batch_size: usize, seq_len: usize) -> Vec<f32> {
115|        let mut output = vec![0.0f32; batch_size * seq_len];
116|
117|        for b in 0..batch_size {
118|            let start = b * seq_len;
119|            let softmax_row = &scores[start..start + seq_len];
120|
121|            // Find max for numerical stability
122|            let max_val = softmax_row
123|                .iter()
124|                .cloned()
125|                .fold(f32::NEG_INFINITY, f32::max);
126|
127|            // Compute exp and sum
128|            let mut sum = 0.0f32;
129|            for i in 0..seq_len {
130|                let exp_val = (softmax_row[i] - max_val).exp();
131|                output[start + i] = exp_val;
132|                sum += exp_val;
133|            }
134|
135|            // Normalize
136|            if sum > 0.0 {
137|                for i in 0..seq_len {
138|                    output[start + i] /= sum;
139|                }
140|            }
141|        }
142|
143|        output
144|    }
145|}
