148|    fn forward(
149|        &self,
150|        query: &DeviceBuffer<f16>,
151|        key_cache: &Kvcache,
152|        value_cache: &Kvcache,
153|        mask: Option<&DeviceBuffer<f32>>,
154|        config: &AttentionConfig,
155|    ) -> Result<DeviceBuffer<f32>, AttentionError> {
156|        self.forward(query, key_cache, value_cache, mask, config)
157|    }
158|
159|    fn is_available(&self) -> bool {
160|        true
161|    }
162|
163|    fn arch(&self) -> AttentionArch {
164|        AttentionArch::Wgmma
165|    }
166|}
