273|    /// Copy device data to a host Vec.
274|    pub fn to_host_vec<B: MemoryBackend>(&self, backend: &B) -> Result<Vec<T>, DeviceBufferError>
275|    where
276|        T: Default + Copy,
277|    {
278|        let bytes = self.byte_len();
279|        let mut buf = vec![T::default(); self.len];
280|        let dst_bytes: &mut [u8] =
